sys_script_include.script:
function HtmlRenderMermaid(strCode)
{
	strCode = GetStringValue(strCode);
	if (strCode == '')
	{
		return '';
	}

	var strHtml = '';

	strHtml += '<div class="mermaid">\n';
	strHtml += strCode + '\n';
	strHtml += '</div>\n';

	strHtml += HtmlRenderStyle(`
		.mermaid
		{
			overflow: auto;
			padding: .75rem;
			background: #ffffff;
			color: #171717;
			text-align: center;
			border-radius: .25rem;
		}

		.mermaid[data-mermaid-theme="dark"]
		{
			background: #252a31;
			color: #f1f3f5;
		}

		.mermaid svg
		{
			max-width: 100%;
			height: auto;
		}
	`);

	strHtml += HtmlRenderScript(`
		if (!window.MermaidSDK)
		{
			const sdk = {
				library: null,
				error: '',
				promise: null,
				renderPromise: Promise.resolve(),
				theme: null,
				sources: new Map()
			};

			window.MermaidSDK = sdk;

			// Detect the active ServiceNow/page theme.
			sdk.getTheme = function()
			{
				const candidates = [document.documentElement, document.body];
				const roots = candidates.filter(Boolean);

				// Recognize explicit theme indicators.
				for (const root of roots)
				{
					const indicators = [
						root.getAttribute('data-theme') || '',
						root.getAttribute('data-color-scheme') || '',
						root.getAttribute('data-mode') || ''
					];

					const joinedIndicators = indicators.join(' ');
					const value = joinedIndicators.toLowerCase();

					if (/\\bdark\\b/.test(value))
						return 'dark';

					if (/\\blight\\b/.test(value))
						return 'default';

					if (root.classList.contains('dark') ||
						root.classList.contains('dark-theme') ||
						root.classList.contains('sn-dark-theme'))
						return 'dark';
				}

				// Check the computed appearance, starting with the body.
				roots.reverse();

				for (const root of roots)
				{
					const style = getComputedStyle(root);
					const colorSchemes = style.colorScheme.split(/\\s+/);

					if (colorSchemes.includes('dark') &&
						!colorSchemes.includes('light'))
						return 'dark';

					const color = style.backgroundColor;
					const match = color.match(
						/^rgba?\\((\\d+)[,\\s]+(\\d+)[,\\s]+(\\d+)/
					);

					if (match)
					{
						const alphaMatch = color.match(
							/[,\\s]+(0(?:\\.\\d+)?|1(?:\\.0+)?)\\)$/
						);

						if (alphaMatch)
						{
							const [, alpha] = alphaMatch;
							if (Number(alpha) <= 0)
								continue;
						}

						const [, red, green, blue] = match;
						const brightness = (
							Number(red) * 299 +
							Number(green) * 587 +
							Number(blue) * 114
						) / 1000;

						return brightness < 128 ? 'dark' : 'default';
					}
				}

				return 'default';
			};

			const modulePromise = import(
				'https://cdn.jsdelivr.net/npm/mermaid@12.3.0/dist/mermaid.esm.min.mjs'
			);

			const initializationPromise = modulePromise.then(function(module)
			{
				const mermaid = module.default;

				mermaid.initialize({
					startOnLoad: false,
					securityLevel: 'strict',
					suppressErrorRendering: true,
					theme: sdk.getTheme(),
					fontFamily: 'Consolas, Courier New, monospace'
				});

				sdk.library = mermaid;
				window.dispatchEvent(new Event('mermaid-sdk-ready'));

				return mermaid;
			});

			sdk.promise = initializationPromise.catch(function(error)
			{
				sdk.error = String(error.message || error);
				window.dispatchEvent(new Event('mermaid-sdk-error'));
				throw error;
			});

			sdk.render = function()
			{
				const queue = sdk.renderPromise.catch(function() {});

				const rendering = queue.then(async function()
				{
					const mermaid = await sdk.promise;

					if (document.readyState === 'loading')
					{
						await new Promise(function(resolve)
						{
							document.addEventListener(
								'DOMContentLoaded',
								resolve,
								{ once: true }
							);
						});
					}

					const theme = sdk.getTheme();
					const diagrams = Array.from(
						document.querySelectorAll('.mermaid')
					);

					// Remember the original Mermaid source.
					for (const element of diagrams)
					{
						if (!sdk.sources.has(element))
							sdk.sources.set(element, element.textContent);
					}

					// Remove references to detached diagrams.
					for (const element of sdk.sources.keys())
					{
						if (!element.isConnected)
							sdk.sources.delete(element);
					}

					// A theme change requires fresh SVG rendering.
					if (sdk.theme !== theme)
					{
						mermaid.initialize({
							startOnLoad: false,
							securityLevel: 'strict',
							suppressErrorRendering: true,
							theme: theme,
							fontFamily: 'Consolas, Courier New, monospace'
						});

						for (const element of diagrams)
						{
							element.textContent = sdk.sources.get(element);
							element.removeAttribute('data-processed');
						}

						sdk.theme = theme;
					}

					for (const element of diagrams)
						element.dataset.mermaidTheme = theme;

					await mermaid.run({
						querySelector: '.mermaid:not([data-processed])'
					});
				});

				sdk.renderPromise = rendering.catch(function(error)
				{
					console.error('Mermaid rendering failed:', error);
				});

				return sdk.renderPromise;
			};

			// Observe changes to page theme attributes.
			sdk.observer = new MutationObserver(function()
			{
				sdk.render();
			});

			sdk.observer.observe(document.documentElement, {
				attributes: true,
				attributeFilter: [
					'class',
					'style',
					'data-theme',
					'data-color-scheme',
					'data-mode'
				],
				subtree: true
			});

			// Also respond to OS theme changes.
			sdk.media = window.matchMedia('(prefers-color-scheme: dark)');

			sdk.media.addEventListener('change', function()
			{
				sdk.render();
			});
		}

		window.MermaidSDK.render();
	`);

	return strHtml;
}
